-- Reels Cinema: script PostgreSQL recuperado de avance1-informe.pdf

CREATE TABLE sala ( id_sala INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, numero_sala INTEGER NOT NULL UNIQUE, capacidad INTEGER NOT NULL, estado VARCHAR(25) NOT NULL DEFAULT 'disponible', CONSTRAINT ck_sala_numero CHECK (numero_sala > 0), CONSTRAINT ck_sala_capacidad CHECK (capacidad > 0), CONSTRAINT ck_sala_estado CHECK ( estado IN ('disponible', 'mantenimiento', 'fuera_servicio') ) );

CREATE TABLE espectador ( id_espectador INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre_completo VARCHAR(150) NOT NULL, correo VARCHAR(254) NOT NULL, telefono VARCHAR(25) NOT NULL, fecha_registro DATE NOT NULL DEFAULT CURRENT_DATE, estado VARCHAR(15) NOT NULL DEFAULT 'activo', CONSTRAINT ck_espectador_nombre CHECK (BTRIM(nombre_completo) <> ''), CONSTRAINT ck_espectador_correo CHECK (BTRIM(correo) <> ''), CONSTRAINT ck_espectador_telefono CHECK (BTRIM(telefono) <> ''), CONSTRAINT ck_espectador_estado CHECK (estado IN ('activo', 'inactivo')) );

CREATE TABLE staff ( id_staff INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre_completo VARCHAR(150) NOT NULL, tipo_documento VARCHAR(20) NOT NULL, numero_documento VARCHAR(30) NOT NULL, cargo VARCHAR(30) NOT NULL, correo VARCHAR(254) NOT NULL, telefono VARCHAR(25) NOT NULL, fecha_ingreso DATE NOT NULL, estado VARCHAR(15) NOT NULL DEFAULT 'activo', CONSTRAINT uq_staff_documento UNIQUE (tipo_documento, numero_documento), CONSTRAINT ck_staff_nombre CHECK (BTRIM(nombre_completo) <> ''), CONSTRAINT ck_staff_tipo_documento CHECK (BTRIM(tipo_documento) <> ''), CONSTRAINT ck_staff_documento CHECK (BTRIM(numero_documento) <> ''), CONSTRAINT ck_staff_correo CHECK (BTRIM(correo) <> ''), CONSTRAINT ck_staff_telefono CHECK (BTRIM(telefono) <> ''), CONSTRAINT ck_staff_cargo CHECK ( cargo IN ('taquillero', 'administrador', 'proyeccionista', 'auxiliar') ), CONSTRAINT ck_staff_estado CHECK (estado IN ('activo', 'inactivo')) );

CREATE TABLE tipo_boleta ( id_tipo_boleta INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, categoria VARCHAR(50) NOT NULL UNIQUE, descripcion TEXT NOT NULL, precio NUMERIC(12,2) NOT NULL, CONSTRAINT ck_tipo_boleta_categoria CHECK (BTRIM(categoria) <> ''), CONSTRAINT ck_tipo_boleta_descripcion CHECK (BTRIM(descripcion) <> ''), CONSTRAINT ck_tipo_boleta_precio CHECK (precio > 0) );

CREATE TABLE pelicula ( id_pelicula INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, titulo VARCHAR(200) NOT NULL, duracion INTEGER NOT NULL, genero VARCHAR(50) NOT NULL, clasificacion_edad VARCHAR(30) NOT NULL, idioma_original VARCHAR(50) NOT NULL, fecha_estreno DATE NOT NULL, CONSTRAINT ck_pelicula_titulo CHECK (BTRIM(titulo) <> ''), CONSTRAINT ck_pelicula_duracion CHECK (duracion > 0), CONSTRAINT ck_pelicula_genero CHECK (BTRIM(genero) <> ''), CONSTRAINT ck_pelicula_clasificacion CHECK (BTRIM(clasificacion_edad) <> ''), CONSTRAINT ck_pelicula_idioma CHECK (BTRIM(idioma_original) <> '') );

CREATE TABLE actores_directores ( id_artista INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre_completo VARCHAR(150) NOT NULL, fecha_nacimiento DATE NOT NULL, nacionalidad VARCHAR(60) NOT NULL, rol VARCHAR(15) NOT NULL, biografia TEXT NOT NULL, CONSTRAINT ck_artista_nombre CHECK (BTRIM(nombre_completo) <> ''), CONSTRAINT ck_artista_nacionalidad CHECK (BTRIM(nacionalidad) <> ''), CONSTRAINT ck_artista_biografia CHECK (BTRIM(biografia) <> ''), CONSTRAINT ck_artista_rol CHECK (rol IN ('actor', 'director', 'ambos')) );

CREATE TABLE funcion ( id_funcion INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sala_id_sala INTEGER NOT NULL, pelicula_id_pelicula INTEGER NOT NULL, fecha_hora_inicio TIMESTAMP NOT NULL, fecha_hora_fin TIMESTAMP NOT NULL, formato_proyeccion VARCHAR(10) NOT NULL, idioma_proyeccion VARCHAR(50) NOT NULL, subtitulada BOOLEAN NOT NULL DEFAULT FALSE, estado VARCHAR(20) NOT NULL DEFAULT 'programada', CONSTRAINT fk_funcion_sala FOREIGN KEY (sala_id_sala) REFERENCES sala(id_sala), CONSTRAINT fk_funcion_pelicula FOREIGN KEY (pelicula_id_pelicula) REFERENCES pelicula(id_pelicula), CONSTRAINT ck_funcion_horario CHECK (fecha_hora_fin > fecha_hora_inicio), CONSTRAINT ck_funcion_formato CHECK (formato_proyeccion IN ('2D', '3D')), CONSTRAINT ck_funcion_idioma CHECK (BTRIM(idioma_proyeccion) <> ''), CONSTRAINT ck_funcion_estado CHECK ( estado IN ('programada', 'cancelada', 'finalizada') ) );

CREATE TABLE venta ( id_venta INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, espectador_id_espectador INTEGER NOT NULL, funcion_id_funcion INTEGER NOT NULL, tipo_boleta_id_tipo_boleta INTEGER NOT NULL, staff_id_staff INTEGER, fecha_hora_venta TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, cantidad_boletas INTEGER NOT NULL, precio_unitario NUMERIC(12,2) NOT NULL, total NUMERIC(14,2) GENERATED ALWAYS AS (cantidad_boletas * precio_unitario) STORED, metodo_pago VARCHAR(20) NOT NULL, canal_venta VARCHAR(15) NOT NULL, estado VARCHAR(15) NOT NULL DEFAULT 'pendiente', CONSTRAINT fk_venta_espectador FOREIGN KEY (espectador_id_espectador) REFERENCES espectador(id_espectador), CONSTRAINT fk_venta_funcion FOREIGN KEY (funcion_id_funcion) REFERENCES funcion(id_funcion), CONSTRAINT fk_venta_tipo_boleta FOREIGN KEY (tipo_boleta_id_tipo_boleta) REFERENCES tipo_boleta(id_tipo_boleta), CONSTRAINT fk_venta_staff FOREIGN KEY (staff_id_staff) REFERENCES staff(id_staff), CONSTRAINT ck_venta_cantidad CHECK (cantidad_boletas > 0), CONSTRAINT ck_venta_precio CHECK (precio_unitario > 0), CONSTRAINT ck_venta_metodo CHECK ( metodo_pago IN ('efectivo', 'tarjeta', 'transferencia') ), CONSTRAINT ck_venta_canal CHECK (canal_venta IN ('taquilla', 'en_linea')), CONSTRAINT ck_venta_estado CHECK (estado IN ('pendiente', 'pagada', 'cancelada')), CONSTRAINT ck_venta_staff_taquilla CHECK ( canal_venta <> 'taquilla' OR staff_id_staff IS NOT NULL ) );

CREATE TABLE contrato ( id_contrato INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actores_directores_id_artista INTEGER NOT NULL, fecha_inicio DATE NOT NULL, fecha_fin DATE NOT NULL, descripcion TEXT NOT NULL, valor NUMERIC(14,2) NOT NULL, estado VARCHAR(15) NOT NULL DEFAULT 'borrador', CONSTRAINT fk_contrato_artista FOREIGN KEY (actores_directores_id_artista) REFERENCES actores_directores(id_artista), CONSTRAINT ck_contrato_fechas CHECK (fecha_fin >= fecha_inicio), CONSTRAINT ck_contrato_descripcion CHECK (BTRIM(descripcion) <> ''), CONSTRAINT ck_contrato_valor CHECK (valor > 0), CONSTRAINT ck_contrato_estado CHECK ( estado IN ('borrador', 'vigente', 'finalizado', 'cancelado') ) );

CREATE TABLE pelicula_actores_directores ( pelicula_id_pelicula INTEGER NOT NULL, actores_directores_id_artista INTEGER NOT NULL, CONSTRAINT pk_pelicula_actores_directores PRIMARY KEY (pelicula_id_pelicula, actores_directores_id_artista), CONSTRAINT fk_pelicula_artista_pelicula FOREIGN KEY (pelicula_id_pelicula) REFERENCES pelicula(id_pelicula), CONSTRAINT fk_pelicula_artista_artista FOREIGN KEY (actores_directores_id_artista) REFERENCES actores_directores(id_artista) );
